fn sum_of_numbers(numbers: Vec<Str>) -> (Int, Int) {
    let mut found = 0;
    let mut not_found = 0;

    for n in numbers {
        match n.parse::<Int>() {
            Ok(num) => {
                found += num;
            },
            Err(_) => {
                not_found += 1;
            }
        }
    }

    (found, not_found)
}

